```python
from dataclasses import dataclass

@dataclass
class OrderInfo:
    total: float
    item_count: int
    tier: str
    is_gift: bool
    country: str
    coupon: bool
    weight: float

# Predicate helpers

def is_invalid(info: OrderInfo) -> bool:
    return info.total <= 0 or info.item_count <= 0

def is_vip_large(info: OrderInfo) -> bool:
    return info.tier == "premium" and info.total > 1000

# ... other predicates ...

# Main classification

def classify_order(info: OrderInfo) -> str:
    if is_invalid(info):
        return "invalid"
    if is_vip_large(info):
        return "vip-large"
    if info.tier == "premium":
        return "vip"
    if info.is_gift and info.country != "TR":
        return "gift-international"
    if info.is_gift:
        return "gift-domestic"
    if info.coupon and info.total > 500:
        return "discounted-large"
    if info.coupon:
        return "discounted"
    if info.weight > 30:
        return "freight"
    if info.total > 1000:
        return "large"
    if info.item_count > 20:
        return "bulk"
    return "standard"
```

